"use client";

import { Building2, ChevronRight, CircleAlert, FileText, FileSearch, FolderOpen, HardDrive, LogOut, Plus, RefreshCw, Search, Send, Settings2, ShieldCheck, Sparkles, Trash2, Unplug, Users, X } from "lucide-react";
import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useState } from "react";
import { useParams, usePathname, useRouter, useSearchParams } from "next/navigation";

const API_BASE = process.env.NEXT_PUBLIC_API_BASE_URL ?? process.env.VITE_API_BASE_URL ?? "http://localhost:8000";
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

type Role = "owner" | "admin" | "member";
type Screen = "home" | "company" | "library" | "team" | "integrations" | "staff" | "invitation";
type Company = { id: string; name: string; membership_id: string; role: Role };
type User = { id: string; email: string; is_platform_staff?: boolean };
type Folder = { id: string; name: string; status: string; last_synced_at: string | null };
type LibraryDocumentRef = { workspace_folder_id: string; document_id: string };
type LibraryNode = { id: string; parent_id: string | null; source_id: string; kind: "source" | "folder" | "file"; name: string; mime_type: string | null; source_url: string | null; workspace_documents?: LibraryDocumentRef[] };
type LibraryPage = { items: LibraryNode[]; page?: number; pages?: number; total?: number };
type LibraryContext = { id: string; name: string; status: string; source_id: string; query_status: "ready" | "no_indexed_content" | "no_compatible_embeddings" };
type LibrarySync = { id: string; source_id: string; workspace_folder_id: string; workspace_name: string; status: string; created_at: string; started_at: string | null; completed_at: string | null; error_code: string | null };
type Member = { id: string; email: string; role: Role };
type Source = { id: string; provider: string; status: string; account_email: string | null };
type RemoteFolder = { id: string; name: string };
type ScopeCatalog = { folders: RemoteFolder[]; root_files: { available: boolean; label: string }; all_accessible: { available: boolean; label: string } };
type Evidence = { document_id: string; document_name: string; excerpt: string; page_number: number | null; source_url: string | null; citation_count?: number };
type Answer = { answer: string | null; confidence: string; citations: Evidence[]; retrieval_status: string };
type ConversationMessage = { id: string; role: "user" | "assistant"; content: string; contextName: string; answer?: Answer; pending?: boolean; error?: string };
type Sync = { id: string; status: string; error_code: string | null; completed_at: string | null };
type FailedDocument = { id: string; name: string; status: string; error_code: string | null };
type StaffCompany = { organization_id: string; name: string; reason: string; expires_at: string; grant_id: string };
type StaffFolder = Folder & { failure_summary: { error_code: string; count: number }[] };
type StaffOverview = { folders: StaffFolder[]; reason: string; expires_at: string };

class ApiError extends Error { constructor(public readonly status: number, message: string) { super(message); } }
async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${API_BASE}${path}`, { credentials: "include", headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) }, ...init });
  if (response.status === 204) return undefined as T;
  if (!response.ok) {
    const body: unknown = await response.json().catch(() => null);
    const detail = typeof body === "object" && body !== null && "detail" in body && typeof body.detail === "string" ? body.detail : "Não foi possível concluir esta ação.";
    throw new ApiError(response.status, detail);
  }
  return response.json() as Promise<T>;
}
const isUuid = (value: string | undefined): value is string => Boolean(value && UUID.test(value));
const isInvitationToken = (value: string | undefined): value is string => Boolean(value && /^[A-Za-z0-9_-]{20,128}$/.test(value));
const messageFor = (error: unknown) => error instanceof Error ? error.message : "Ocorreu um erro inesperado.";
const companyPath = (companyId: string, suffix = "") => `/companies/${companyId}${suffix}`;
const contextStatusLabel = (context: LibraryContext) => context.query_status === "ready" ? "Pronto para perguntas" : context.query_status === "no_indexed_content" ? "Sem conteúdo indexado" : "Indexação de IA pendente";
const retrievalMessage = (status: string) => status === "no_indexed_content" ? "Ainda não há conteúdo consultável neste escopo. Aguarde a sincronização ou escolha outra pasta." : status === "no_compatible_embeddings" ? "O conteúdo foi encontrado, mas a indexação de IA ainda não terminou. Tente novamente em alguns instantes." : status === "invalid_generation_output" ? "Encontrei trechos relevantes, mas não foi possível produzir uma resposta verificável. Tente novamente." : "Não encontrei evidência suficiente neste escopo para responder com segurança.";
const compactCitations = (citations: Evidence[]): Evidence[] => {
  const grouped = new Map<string, Evidence>();
  for (const citation of citations) {
    const existing = grouped.get(citation.document_id);
    if (!existing) { grouped.set(citation.document_id, { ...citation, citation_count: 1 }); continue; }
    existing.citation_count = (existing.citation_count ?? 1) + 1;
    if (!existing.source_url && citation.source_url) existing.source_url = citation.source_url;
  }
  return [...grouped.values()];
};

export function ProductApp({ screen }: { screen: Screen }) {
  const router = useRouter(); const pathname = usePathname(); const searchParams = useSearchParams(); const params = useParams<{ companyId?: string; token?: string }>();
  const [user, setUser] = useState<User | null>(null); const [companies, setCompanies] = useState<Company[]>([]); const [loading, setLoading] = useState(true); const [notice, setNotice] = useState<string | null>(null); const [error, setError] = useState<string | null>(null);
  const loadSession = useCallback(async () => {
    try { const [current, memberships] = await Promise.all([api<User>("/me"), api<Company[]>("/organizations")]); setUser(current); setCompanies(memberships); if (screen === "home" && memberships[0]) router.replace(companyPath(memberships[0].id)); }
    catch (caught) { if (!(caught instanceof ApiError && caught.status === 401)) setError(messageFor(caught)); }
    finally { setLoading(false); }
  }, [router, screen]);
  useEffect(() => { void Promise.resolve().then(loadSession); }, [loadSession]);
  const oauthNotice = screen === "integrations" && searchParams.get("connected") === "google_drive" ? "Google Drive conectado. Abra a ferramenta para definir o escopo e iniciar uma sincronização." : null;
  const dismissAlert = useCallback(() => { setNotice(null); setError(null); if (oauthNotice) router.replace(pathname); }, [oauthNotice, pathname, router]);
  const alertMessage = error ?? notice ?? oauthNotice;
  useEffect(() => {
    if (!alertMessage) return;
    const timeout = window.setTimeout(dismissAlert, 6000);
    return () => window.clearTimeout(timeout);
  }, [alertMessage, dismissAlert]);
  const company = useMemo(() => companies.find((item) => item.id === params.companyId) ?? null, [companies, params.companyId]);
  const goCompany = (id: string) => { const suffix = pathname.endsWith("/team") ? "/team" : pathname.endsWith("/integrations") ? "/integrations" : pathname.endsWith("/library") ? "/library" : ""; router.push(companyPath(id, suffix)); };
  const beginLogin = (screenHint: "sign-in" | "sign-up") => { const query = new URLSearchParams({ screen_hint: screenHint }); if (screen === "invitation" && isInvitationToken(params.token)) query.set("return_to", pathname); window.location.assign(`${API_BASE}/auth/login?${query.toString()}`); };
  const logout = async () => { try { const { redirect_url } = await api<{ redirect_url: string }>("/auth/logout", { method: "POST" }); setUser(null); setCompanies([]); window.location.assign(redirect_url); } catch (caught) { setError(messageFor(caught)); } };
  if (loading) return <Loading />;
  if (!user) return <SignIn onLogin={() => beginLogin("sign-in")} onSignUp={() => beginLogin("sign-up")} />;
  if (screen === "invitation") return <InvitationAcceptance token={params.token} onAccepted={(organizationId) => router.replace(companyPath(organizationId))} />;
  if (screen === "home") return <Onboarding user={user} onCreated={(created) => { setCompanies((items) => [...items, created]); router.push(companyPath(created.id)); }} />;
  if (screen === "staff") return <StaffCenter user={user} onBack={() => router.push(companies[0] ? companyPath(companies[0].id) : "/")} />;
  if (!isUuid(params.companyId) || !company) return <InvalidCompany companies={companies} onChoose={goCompany} />;
  return <Shell user={user} company={company} companies={companies} alertMessage={alertMessage} alertTone={error ? "error" : "notice"} fillViewport={screen === "company" || screen === "library"} pageSurface={screen === "team" || screen === "integrations"} onDismiss={dismissAlert} onCompanyChange={goCompany} onNavigate={(path) => router.push(path)} onLogout={() => { void logout(); }}>
    {screen === "company" && <CompanyDashboard company={company} onConnect={() => router.push(companyPath(company.id, "/integrations"))} setError={setError} setNotice={setNotice} />}
    {screen === "library" && <LibraryScreen company={company} onConnect={() => router.push(companyPath(company.id, "/integrations"))} setError={setError} setNotice={setNotice} />}
    {screen === "team" && <TeamScreen company={company} setError={setError} setNotice={setNotice} />}
    {screen === "integrations" && <IntegrationScreen company={company} setError={setError} setNotice={setNotice} onOpenWorkspace={() => router.push(companyPath(company.id, "/library"))} />}
  </Shell>;
}

function Loading() { return <main className="grid min-h-screen place-items-center bg-slate-950 text-white"><div className="text-center"><Sparkles className="mx-auto mb-3 animate-pulse" /><p>Preparando seu espaço de conhecimento…</p></div></main>; }
function SignIn({ onLogin, onSignUp }: { onLogin: () => void; onSignUp: () => void }) { return <main className="grid min-h-screen place-items-center bg-slate-950 p-6 text-white"><section className="w-full max-w-md rounded-3xl border border-white/10 bg-white/5 p-8 shadow-2xl"><div className="grid size-11 place-items-center rounded-2xl bg-cyan-300 text-slate-950"><FileSearch /></div><h1 className="mt-6 text-3xl font-semibold tracking-tight">Conhecimento que mostra a fonte.</h1><p className="mt-3 leading-6 text-slate-300">Acesse sua base de conhecimento ou crie uma conta para começar.</p><div className="mt-7 space-y-3"><button onClick={onLogin} className="w-full rounded-xl bg-cyan-300 px-4 py-3 font-semibold text-slate-950 hover:bg-cyan-200">Entrar</button><button onClick={onSignUp} className="w-full rounded-xl border border-white/20 bg-white/5 px-4 py-3 font-semibold text-white hover:bg-white/10">Criar conta</button></div></section></main>; }
function InvitationAcceptance({ token, onAccepted }: { token: string | undefined; onAccepted: (organizationId: string) => void }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  if (!isInvitationToken(token)) return <main className="grid min-h-screen place-items-center bg-slate-950 p-6 text-white"><section className="max-w-md text-center"><CircleAlert className="mx-auto text-amber-300" size={34} /><h1 className="mt-4 text-2xl font-semibold">Convite indisponível</h1><p className="mt-3 text-slate-300">Este link não é válido. Peça um novo convite ao Owner da Company.</p></section></main>;
  async function accept() { setBusy(true); setError(null); try { const accepted = await api<{ organization_id: string }>(`/invitations/${encodeURIComponent(token)}/accept`, { method: "POST" }); onAccepted(accepted.organization_id); } catch (caught) { setError(caught instanceof ApiError && caught.status === 404 ? "Este convite expirou, já foi usado ou não pertence ao seu e-mail." : messageFor(caught)); } finally { setBusy(false); } }
  return <main className="grid min-h-screen place-items-center bg-slate-950 p-6 text-white"><section className="w-full max-w-md rounded-3xl border border-white/10 bg-white/5 p-8 shadow-2xl"><Users className="text-cyan-300" size={34} /><p className="mt-6 text-sm font-semibold text-cyan-300">Convite para uma Company</p><h1 className="mt-2 text-3xl font-semibold">Participar da equipe</h1><p className="mt-3 leading-6 text-slate-300">Ao aceitar, você terá acesso somente aos recursos compartilhados com os Members desta Company.</p>{error && <p className="mt-4 rounded-xl border border-rose-300/30 bg-rose-500/10 p-3 text-sm text-rose-200">{error}</p>}<button disabled={busy} onClick={() => { void accept(); }} className="mt-7 w-full rounded-xl bg-cyan-300 px-4 py-3 font-semibold text-slate-950 disabled:opacity-50">{busy ? "Aceitando…" : "Aceitar convite"}</button></section></main>;
}
function Onboarding({ user, onCreated }: { user: User; onCreated: (company: Company) => void }) {
  const [name, setName] = useState(""); const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null);
  async function create(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { const created = await api<{ id: string; membership_id: string; role: Role }>("/organizations", { method: "POST", body: JSON.stringify({ name }) }); onCreated({ ...created, name }); } catch (caught) { setError(messageFor(caught)); } finally { setBusy(false); } }
  return <main className="grid min-h-screen place-items-center bg-slate-950 p-6 text-white"><section className="w-full max-w-lg rounded-3xl border border-white/10 bg-white/5 p-8"><Building2 className="text-cyan-300" size={34} /><p className="mt-6 text-sm text-slate-400">{user.email}</p><h1 className="mt-2 text-3xl font-semibold">Crie sua primeira Company</h1><p className="mt-3 leading-6 text-slate-300">Uma Company isola pessoas, pastas, consultas e fontes. Você será o Owner e poderá convidar a equipe.</p><form onSubmit={create} className="mt-7"><label htmlFor="company-name" className="text-sm font-medium">Nome da Company</label><input id="company-name" required maxLength={160} value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Estúdio Aurora" className="mt-2 w-full rounded-xl border border-white/20 bg-white/10 px-4 py-3 outline-none ring-cyan-300 focus:ring-2" />{error && <p className="mt-3 text-sm text-rose-300">{error}</p>}<button disabled={busy || !name.trim()} className="mt-5 inline-flex items-center gap-2 rounded-xl bg-cyan-300 px-5 py-3 font-semibold text-slate-950 disabled:opacity-50"><Plus size={17} />{busy ? "Criando…" : "Criar Company"}</button></form></section></main>;
}
function InvalidCompany({ companies, onChoose }: { companies: Company[]; onChoose: (id: string) => void }) { return <main className="grid min-h-screen place-items-center bg-slate-950 p-6 text-white"><section className="max-w-md text-center"><CircleAlert className="mx-auto text-amber-300" size={34} /><h1 className="mt-4 text-2xl font-semibold">Essa Company não está disponível</h1><p className="mt-3 text-slate-300">Os IDs na URL são UUIDs, mas isso não autoriza acesso. Escolha uma Company da qual você participa.</p><div className="mt-6 space-y-2">{companies.map((company) => <button key={company.id} onClick={() => onChoose(company.id)} className="flex w-full items-center justify-between rounded-xl bg-white/10 px-4 py-3 text-left hover:bg-white/15"><span>{company.name}</span><ChevronRight size={16} /></button>)}</div></section></main>; }

function NotificationToast({ message, tone, onDismiss }: { message: string; tone: "notice" | "error"; onDismiss: () => void }) {
  const error = tone === "error";
  return <div className="pointer-events-none fixed inset-x-4 top-20 z-50 flex justify-end sm:inset-x-6" aria-live="polite">
    <div role={error ? "alert" : "status"} className={`pointer-events-auto w-full max-w-md overflow-hidden rounded-2xl border bg-white shadow-xl ${error ? "border-rose-200" : "border-emerald-200"}`}>
      <div className="flex items-start gap-3 px-4 py-3.5"><CircleAlert className={`mt-0.5 shrink-0 ${error ? "text-rose-600" : "text-emerald-600"}`} size={18} /><p className={`min-w-0 flex-1 text-sm leading-5 ${error ? "text-rose-900" : "text-emerald-900"}`}>{message}</p><button onClick={onDismiss} className="-mr-1 -mt-1 rounded-lg p-1.5 text-slate-500 hover:bg-slate-100 hover:text-slate-800" aria-label="Fechar aviso"><X size={16} /></button></div>
      <div key={`${tone}-${message}`} className={`h-1 origin-left animate-[toast-progress_6000ms_linear_forwards] ${error ? "bg-rose-500" : "bg-emerald-500"}`} />
    </div>
  </div>;
}

function Shell({ user, company, companies, children, alertMessage, alertTone, fillViewport, pageSurface, onDismiss, onCompanyChange, onNavigate, onLogout }: { user: User; company: Company; companies: Company[]; children: ReactNode; alertMessage: string | null; alertTone: "notice" | "error"; fillViewport: boolean; pageSurface: boolean; onDismiss: () => void; onCompanyChange: (id: string) => void; onNavigate: (path: string) => void; onLogout: () => void }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const canManage = company.role !== "member";
  const go = (suffix = "") => { setMenuOpen(false); onNavigate(companyPath(company.id, suffix)); };
  return <main className={`${fillViewport ? "flex h-dvh flex-col overflow-hidden" : "min-h-screen"} bg-slate-50 text-slate-900`}>
    <header className="z-20 shrink-0 border-b border-slate-200 bg-white/95 backdrop-blur">
      <div className="mx-auto flex max-w-7xl items-center gap-3 px-4 py-3">
        <button onClick={() => go()} className="grid size-9 place-items-center rounded-xl bg-slate-950 text-cyan-300" aria-label="Ir para consultas"><FileSearch size={18} /></button>
        <select aria-label="Company ativa" value={company.id} onChange={(event) => onCompanyChange(event.target.value)} className="max-w-52 rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-semibold">{companies.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select>
        <span className="hidden rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold capitalize text-slate-600 sm:inline">{company.role}</span>
        <div className="ml-auto flex items-center gap-2">
          <span className="hidden text-sm text-slate-500 md:block">{user.email}</span>
          {user.is_platform_staff && <button onClick={() => { setMenuOpen(false); onNavigate("/staff"); }} className="rounded-lg border border-violet-200 px-3 py-2 text-xs font-semibold text-violet-700"><ShieldCheck className="mr-1 inline" size={14} />Suporte</button>}
          <div className="relative">
            <button onClick={() => setMenuOpen((open) => !open)} aria-expanded={menuOpen} aria-haspopup="menu" className="inline-flex items-center gap-1.5 rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-50"><span className="hidden sm:inline">Navegar</span><ChevronRight size={16} className={`transition-transform ${menuOpen ? "rotate-90" : ""}`} /></button>
            {menuOpen && <div role="menu" className="absolute right-0 mt-2 w-60 overflow-hidden rounded-2xl border border-slate-200 bg-white p-1.5 shadow-xl">
              <button role="menuitem" onClick={() => go()} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold text-slate-800 hover:bg-cyan-50"><Sparkles size={16} className="text-cyan-700" /><span><span className="block">Consultas</span><span className="block text-xs font-normal text-slate-500">Voltar à conversa</span></span></button>
              <button role="menuitem" onClick={() => go("/library")} className="mt-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold text-slate-800 hover:bg-cyan-50"><FolderOpen size={16} className="text-cyan-700" /><span><span className="block">Biblioteca</span><span className="block text-xs font-normal text-slate-500">Explore e gerencie o índice</span></span></button>
              {company.role === "owner" && <button role="menuitem" onClick={() => go("/team")} className="mt-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold text-slate-800 hover:bg-cyan-50"><Users size={16} className="text-cyan-700" /><span><span className="block">Equipe</span><span className="block text-xs font-normal text-slate-500">Membros e convites</span></span></button>}
              {canManage && <button role="menuitem" onClick={() => go("/integrations")} className="mt-1 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold text-slate-800 hover:bg-cyan-50"><HardDrive size={16} className="text-cyan-700" /><span><span className="block">Tools</span><span className="block text-xs font-normal text-slate-500">Fontes e sincronizações</span></span></button>}
            </div>}
          </div>
          <button onClick={onLogout} title="Sair" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><LogOut size={18} /></button>
        </div>
      </div>
    </header>
    {alertMessage && <NotificationToast message={alertMessage} tone={alertTone} onDismiss={onDismiss} />}
    <div className={`mx-auto w-full max-w-7xl p-4 ${fillViewport ? "min-h-0 flex-1" : ""}`}><section className={`min-w-0 ${fillViewport ? "workspace-shell h-full min-h-0" : ""} ${pageSurface ? "page-surface" : ""}`}>{children}</section></div>
  </main>;
}

function CompanyDashboard({ company, onConnect, setError, setNotice }: { company: Company; onConnect: () => void; setError: (value: string | null) => void; setNotice: (value: string | null) => void }) {
  return <ConversationLibraryWorkspace key={company.id} company={company} onConnect={onConnect} setError={setError} setNotice={setNotice} />;
}

function LibraryScreen({ company, onConnect, setError, setNotice }: { company: Company; onConnect: () => void; setError: (value: string | null) => void; setNotice: (value: string | null) => void }) {
  const [path, setPath] = useState<LibraryNode[]>([]); const [items, setItems] = useState<LibraryNode[]>([]); const [folders, setFolders] = useState<Folder[]>([]); const [loading, setLoading] = useState(true); const [busyFolderId, setBusyFolderId] = useState<string | null>(null); const [managedFile, setManagedFile] = useState<LibraryNode | null>(null); const [managedDocument, setManagedDocument] = useState<LibraryDocumentRef | null>(null); const [managingFile, setManagingFile] = useState(false);
  const canManage = company.role !== "member"; const current = path.at(-1);
  const loadItems = useCallback(() => { setLoading(true); const request = current ? `/library/nodes/${current.id}/children?organization_id=${company.id}` : `/library?organization_id=${company.id}`; void api<LibraryPage>(request).then((result) => setItems(result.items)).catch((caught) => setError(messageFor(caught))).finally(() => setLoading(false)); }, [company.id, current, setError]);
  const loadFolders = useCallback(() => { void api<Folder[]>(`/workspace-folders?organization_id=${company.id}`).then(setFolders).catch((caught) => setError(messageFor(caught))); }, [company.id, setError]);
  useEffect(() => { void Promise.resolve().then(loadItems); }, [loadItems]); useEffect(() => { loadFolders(); }, [loadFolders]);
  function openItem(item: LibraryNode) { if (item.kind === "file") { if (item.source_url) window.open(item.source_url, "_blank", "noopener,noreferrer"); return; } setPath((nodes) => [...nodes, item]); }
  function manageFile(item: LibraryNode) { const reference = item.workspace_documents?.[0] ?? null; if (!reference) { setError("Este arquivo não possui uma cópia indexada disponível para gerenciar."); return; } setManagedFile(item); setManagedDocument(reference); }
  async function syncFolder(folder: Folder) { setBusyFolderId(folder.id); setError(null); try { await api<{ job_id: string; status: string }>(`/workspace-folders/${folder.id}/sync?organization_id=${company.id}`, { method: "POST" }); setNotice(`Sincronização de “${folder.name}” iniciada em segundo plano.`); loadFolders(); } catch (caught) { setError(messageFor(caught)); } finally { setBusyFolderId(null); } }
  async function removeFolder(folder: Folder) { if (!window.confirm(`Remover “${folder.name}” desta base? Isso apaga documentos, embeddings e consultas salvas somente do índice local. Nenhum arquivo ou pasta será apagado do Google Drive.`)) return; setBusyFolderId(folder.id); setError(null); try { await api<void>(`/workspace-folders/${folder.id}?organization_id=${company.id}`, { method: "DELETE" }); setNotice(`O escopo “${folder.name}” foi removido do índice local.`); if (managedDocument?.workspace_folder_id === folder.id) { setManagedFile(null); setManagedDocument(null); } loadFolders(); loadItems(); } catch (caught) { setError(messageFor(caught)); } finally { setBusyFolderId(null); } }
  async function reprocessFile() { if (!managedFile || !managedDocument) return; setManagingFile(true); try { await api<{ job_id: string; status: string }>(`/workspace-folders/${managedDocument.workspace_folder_id}/documents/${managedDocument.document_id}/reprocess?organization_id=${company.id}`, { method: "POST" }); setNotice(`Reprocessamento de “${managedFile.name}” agendado.`); setManagedFile(null); setManagedDocument(null); loadFolders(); } catch (caught) { setError(messageFor(caught)); } finally { setManagingFile(false); } }
  async function removeFile() { if (!managedFile || !managedDocument) return; if (!window.confirm(`Remover “${managedFile.name}” somente deste índice local? O original continuará no Google Drive.`)) return; setManagingFile(true); try { await api<void>(`/workspace-folders/${managedDocument.workspace_folder_id}/documents/${managedDocument.document_id}?organization_id=${company.id}`, { method: "DELETE" }); setNotice(`“${managedFile.name}” foi removido do índice local.`); setManagedFile(null); setManagedDocument(null); loadItems(); loadFolders(); } catch (caught) { setError(messageFor(caught)); } finally { setManagingFile(false); } }
  const references = managedFile?.workspace_documents ?? []; const selectedScope = managedDocument ? folders.find((folder) => folder.id === managedDocument.workspace_folder_id) : null;
  return <><div className="overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm"><header className="flex flex-wrap items-center justify-between gap-4 border-b border-slate-200 px-5 py-5"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-cyan-700">{company.name}</p><h1 className="mt-1 text-2xl font-semibold tracking-tight text-slate-950">Biblioteca</h1><p className="mt-1 text-sm text-slate-500">Explore a estrutura indexada e gerencie seus espaços de conhecimento.</p></div>{canManage && <button onClick={onConnect} className="inline-flex items-center gap-2 rounded-xl bg-slate-950 px-3.5 py-2 text-sm font-semibold text-white hover:bg-slate-800"><Plus size={16} />Adicionar fonte</button>}</header><div className="grid min-h-[calc(100vh-14rem)] xl:grid-cols-[270px_minmax(0,1fr)_320px]"><aside className="border-b border-slate-200 bg-slate-50/80 p-3 xl:border-b-0 xl:border-r"><div className="flex items-center justify-between px-1 pb-3"><div><p className="text-sm font-semibold">Estrutura</p><p className="text-xs text-slate-500">Fontes e pastas</p></div><button onClick={loadItems} className="rounded-lg p-2 text-slate-500 hover:bg-white" aria-label="Atualizar estrutura"><RefreshCw size={15} /></button></div><nav className="mb-3 flex flex-wrap items-center gap-1 text-xs"><button onClick={() => setPath([])} className={`rounded-md px-2 py-1.5 ${path.length === 0 ? "bg-white font-semibold shadow-sm" : "text-cyan-700"}`}>Biblioteca</button>{path.map((node, index) => <span key={node.id} className="flex items-center"><ChevronRight size={13} className="text-slate-400" /><button onClick={() => setPath(path.slice(0, index + 1))} className="max-w-28 truncate rounded-md px-1.5 py-1.5 text-cyan-700">{node.name}</button></span>)}</nav><div className="space-y-1">{loading ? <p className="p-3 text-sm text-slate-500">Abrindo estrutura…</p> : items.length === 0 ? <p className="p-3 text-sm text-slate-500">Nenhum item neste nível.</p> : items.map((item) => <button key={item.id} onClick={() => openItem(item)} className="flex w-full items-center gap-2 rounded-xl px-2.5 py-2 text-left text-sm hover:bg-white"><span className={`grid size-7 place-items-center rounded-lg ${item.kind === "file" ? "bg-slate-200 text-slate-600" : "bg-cyan-100 text-cyan-800"}`}>{item.kind === "file" ? <FileText size={14} /> : <FolderOpen size={14} />}</span><span className="min-w-0 flex-1 truncate">{item.name}</span>{item.kind !== "file" && <ChevronRight size={15} className="text-slate-400" />}</button>)}</div></aside><main className="min-w-0 p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="text-sm font-semibold text-slate-900">{current?.name ?? "Todas as fontes"}</p><p className="mt-1 text-sm text-slate-500">Clique em uma pasta para navegar. Clique em um arquivo para abrir a origem.</p></div><span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs text-slate-600">{items.length} itens</span></div><div className="mt-6 grid gap-2 sm:grid-cols-2">{items.map((item) => <div key={item.id} className="flex min-w-0 items-center rounded-2xl border border-slate-200 bg-white p-3 hover:border-cyan-200"><button onClick={() => openItem(item)} className="flex min-w-0 flex-1 items-center gap-3 text-left"><span className={`grid size-10 place-items-center rounded-xl ${item.kind === "file" ? "bg-slate-100 text-slate-600" : "bg-cyan-100 text-cyan-800"}`}>{item.kind === "file" ? <FileText size={18} /> : <FolderOpen size={18} />}</span><span className="min-w-0"><b className="block truncate text-sm text-slate-800">{item.name}</b><span className="mt-0.5 block text-xs text-slate-500">{item.kind === "file" ? "Arquivo indexado" : "Pasta"}</span></span></button>{canManage && item.kind === "file" && (item.workspace_documents?.length ?? 0) > 0 && <button onClick={() => manageFile(item)} title="Gerenciar arquivo" aria-label={`Gerenciar ${item.name}`} className="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><Settings2 size={16} /></button>}</div>)}</div></main><aside className="border-t border-slate-200 bg-slate-50/50 p-4 xl:border-l xl:border-t-0"><div className="flex items-center justify-between"><div><p className="text-sm font-semibold">Espaços sincronizados</p><p className="mt-1 text-xs leading-5 text-slate-500">Ações aplicam-se ao índice local do escopo.</p></div><button onClick={loadFolders} className="rounded-lg p-2 text-slate-500 hover:bg-white" aria-label="Atualizar espaços"><RefreshCw size={15} /></button></div><div className="mt-4 space-y-3">{folders.length === 0 ? <p className="rounded-xl border border-dashed p-4 text-sm text-slate-500">Nenhum espaço sincronizado.</p> : folders.map((folder) => <article key={folder.id} className="rounded-2xl border border-slate-200 bg-white p-4"><div className="flex items-start justify-between gap-2"><b className="min-w-0 truncate text-sm text-slate-800">{folder.name}</b><span className={`rounded-full px-2 py-0.5 text-[11px] font-semibold ${folder.status === "ready" ? "bg-emerald-100 text-emerald-800" : folder.status === "partial_failure" ? "bg-amber-100 text-amber-800" : "bg-cyan-100 text-cyan-800"}`}>{folder.status === "ready" ? "Pronto" : folder.status === "partial_failure" ? "Com falhas" : folder.status}</span></div><p className="mt-2 text-xs text-slate-500">{folder.last_synced_at ? `Última sincronização: ${new Date(folder.last_synced_at).toLocaleString("pt-BR")}` : "Ainda não sincronizado"}</p>{canManage && <div className="mt-4 flex gap-2"><button disabled={busyFolderId === folder.id} onClick={() => { void syncFolder(folder); }} className="inline-flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-slate-300 px-2 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50"><RefreshCw size={14} />Ressincronizar</button><button disabled={busyFolderId === folder.id} onClick={() => { void removeFolder(folder); }} className="inline-flex items-center justify-center rounded-lg border border-rose-200 px-2.5 text-rose-700 hover:bg-rose-50 disabled:opacity-50" title="Remover escopo do índice"><Trash2 size={15} /></button></div>}</article>)}</div></aside></div></div>{managedFile && managedDocument && <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4" role="dialog" aria-modal="true" aria-labelledby="library-file-management"><section className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-wide text-cyan-700">Índice local</p><h2 id="library-file-management" className="mt-1 text-xl font-semibold">Gerenciar arquivo</h2></div><button disabled={managingFile} onClick={() => { setManagedFile(null); setManagedDocument(null); }} className="rounded-lg p-2 text-slate-500 hover:bg-slate-100" aria-label="Fechar"><X size={18} /></button></div><div className="mt-5 rounded-xl bg-slate-50 p-4"><b className="block text-slate-900">{managedFile.name}</b><p className="mt-1 text-sm leading-6 text-slate-500">O arquivo original no Google Drive não será alterado.</p></div>{references.length > 1 && <label className="mt-5 block text-sm font-medium">Espaço de conhecimento<select value={managedDocument.document_id} disabled={managingFile} onChange={(event) => setManagedDocument(references.find((reference) => reference.document_id === event.target.value) ?? null)} className="mt-2 w-full rounded-xl border border-slate-300 px-3 py-2.5 text-sm">{references.map((reference) => <option key={reference.document_id} value={reference.document_id}>{folders.find((folder) => folder.id === reference.workspace_folder_id)?.name ?? "Espaço sincronizado"}</option>)}</select></label>}<p className="mt-4 text-xs text-slate-500">{selectedScope ? `Espaço selecionado: ${selectedScope.name}` : "Espaço selecionado para esta cópia."}</p><div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button disabled={managingFile} onClick={() => { void removeFile(); }} className="inline-flex items-center justify-center gap-2 rounded-xl border border-rose-200 px-4 py-2.5 text-sm font-semibold text-rose-700 hover:bg-rose-50 disabled:opacity-50"><Trash2 size={16} />Remover do índice</button><button disabled={managingFile} onClick={() => { void reprocessFile(); }} className="inline-flex items-center justify-center gap-2 rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50"><RefreshCw size={16} />{managingFile ? "Aguarde…" : "Reprocessar"}</button></div></section></div>}</>;
}

function ConversationLibraryWorkspace({ company, onConnect, setError, setNotice }: { company: Company; onConnect: () => void; setError: (value: string | null) => void; setNotice: (value: string | null) => void }) {
  const [path, setPath] = useState<LibraryNode[]>([]);
  const [items, setItems] = useState<LibraryNode[]>([]);
  const [page, setPage] = useState(1);
  const [pagination, setPagination] = useState<{ page: number; pages: number; total: number } | null>(null);
  const [libraryLoading, setLibraryLoading] = useState(true);
  const [contexts, setContexts] = useState<LibraryContext[]>([]);
  const [syncs, setSyncs] = useState<LibrarySync[]>([]);
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<LibraryNode[]>([]);
  const [contextId, setContextId] = useState("");
  const [question, setQuestion] = useState("");
  const [messages, setMessages] = useState<ConversationMessage[]>([]);
  const [asking, setAsking] = useState(false);
  const [managedFile, setManagedFile] = useState<LibraryNode | null>(null);
  const [managedDocument, setManagedDocument] = useState<LibraryDocumentRef | null>(null);
  const [managingFile, setManagingFile] = useState(false);
  const current = path.at(-1);
  const canManage = company.role !== "member";
  const activeContext = contexts.find((item) => item.id === contextId) ?? null;

  const loadLibrary = useCallback(() => {
    setLibraryLoading(true);
    const request = current ? `/library/nodes/${current.id}/children?organization_id=${company.id}&page=${page}` : `/library?organization_id=${company.id}`;
    void api<LibraryPage>(request)
      .then((result) => {
        setItems(result.items);
        setPagination(typeof result.page === "number" && typeof result.pages === "number" && typeof result.total === "number" ? { page: result.page, pages: result.pages, total: result.total } : null);
      })
      .catch((caught) => setError(messageFor(caught)))
      .finally(() => setLibraryLoading(false));
  }, [company.id, current, page, setError]);
  const loadOperations = useCallback(() => {
    void Promise.all([
      api<{ items: LibraryContext[] }>(`/library/question-contexts?organization_id=${company.id}`),
      api<{ items: LibrarySync[] }>(`/library/syncs?organization_id=${company.id}`),
    ])
      .then(([nextContexts, nextSyncs]) => { setContexts(nextContexts.items); setSyncs(nextSyncs.items); })
      .catch((caught) => setError(messageFor(caught)));
  }, [company.id, setError]);
  useEffect(() => { void Promise.resolve().then(loadLibrary); }, [loadLibrary]);
  useEffect(() => { loadOperations(); }, [loadOperations]);
  useEffect(() => {
    if (!syncs.some((item) => item.status === "queued" || item.status === "syncing")) return;
    const timer = window.setInterval(loadOperations, 5000);
    return () => window.clearInterval(timer);
  }, [loadOperations, syncs]);

  function openItem(item: LibraryNode) {
    if (item.kind === "file") {
      if (item.source_url) window.open(item.source_url, "_blank", "noopener,noreferrer");
      return;
    }
    setPage(1);
    setPath((nodes) => [...nodes, item]);
  }
  function openPath(nodes: LibraryNode[]) { setPage(1); setPath(nodes); }
  function manageFile(item: LibraryNode) {
    const references = item.workspace_documents ?? [];
    const preferred = references.find((reference) => reference.workspace_folder_id === contextId) ?? references[0] ?? null;
    if (!preferred) { setError("Este arquivo não possui uma cópia indexada disponível para gerenciar."); return; }
    setManagedFile(item); setManagedDocument(preferred);
  }
  async function reprocessManagedFile() {
    if (!managedFile || !managedDocument) return;
    setManagingFile(true); setError(null);
    try {
      await api<{ job_id: string; status: string }>(`/workspace-folders/${managedDocument.workspace_folder_id}/documents/${managedDocument.document_id}/reprocess?organization_id=${company.id}`, { method: "POST" });
      setManagedFile(null); setManagedDocument(null); loadOperations();
      setNotice(`Reprocessamento de “${managedFile.name}” agendado. A extração e os embeddings serão atualizados em segundo plano.`);
    } catch (caught) { setError(messageFor(caught)); } finally { setManagingFile(false); }
  }
  async function removeManagedFile() {
    if (!managedFile || !managedDocument) return;
    if (!window.confirm(`Remover “${managedFile.name}” somente desta base de conhecimento? O arquivo original continuará no Google Drive. Uma nova sincronização deste escopo poderá indexá-lo novamente.`)) return;
    setManagingFile(true); setError(null);
    try {
      await api<void>(`/workspace-folders/${managedDocument.workspace_folder_id}/documents/${managedDocument.document_id}?organization_id=${company.id}`, { method: "DELETE" });
      setManagedFile(null); setManagedDocument(null); await Promise.all([Promise.resolve(loadLibrary()), Promise.resolve(loadOperations())]);
      setNotice(`“${managedFile.name}” foi removido apenas do índice local.`);
    } catch (caught) { setError(messageFor(caught)); } finally { setManagingFile(false); }
  }
  async function searchLibrary(event: FormEvent) {
    event.preventDefault();
    if (!query.trim()) { setResults([]); return; }
    try {
      const found = await api<{ items: LibraryNode[] }>(`/library/search?organization_id=${company.id}&query=${encodeURIComponent(query)}`);
      setResults(found.items);
    } catch (caught) { setError(messageFor(caught)); }
  }
  async function ask(event: FormEvent) {
    event.preventDefault();
    const submittedQuestion = question.trim();
    if (!activeContext || activeContext.query_status !== "ready" || !submittedQuestion) return;
    const requestId = crypto.randomUUID();
    const pendingId = `${requestId}:assistant`;
    setMessages((items) => [
      ...items,
      { id: requestId, role: "user", content: submittedQuestion, contextName: activeContext.name },
      { id: pendingId, role: "assistant", content: "", contextName: activeContext.name, pending: true },
    ]);
    setQuestion("");
    setAsking(true);
    try {
      const result = await api<Answer>(`/workspace-folders/${activeContext.id}/questions?organization_id=${company.id}`, { method: "POST", body: JSON.stringify({ question: submittedQuestion }) });
      const answer = { ...result, citations: compactCitations(result.citations) };
      setMessages((items) => items.map((item) => item.id === pendingId ? { ...item, pending: false, answer } : item));
    } catch (caught) {
      const error = messageFor(caught);
      setMessages((items) => items.map((item) => item.id === pendingId ? { ...item, pending: false, error } : item));
      setError(error);
    }
    finally { setAsking(false); }
  }
  const activeSyncs = syncs.filter((item) => item.status === "queued" || item.status === "syncing");
  const visibleSyncs = activeSyncs.length > 0 ? activeSyncs : syncs.slice(0, 3);

  const managedReferences = managedFile?.workspace_documents ?? [];
  const managedContext = managedDocument ? contexts.find((item) => item.id === managedDocument.workspace_folder_id) : null;
  return <><div className="overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm">
    <div className="border-b border-slate-200 bg-white px-5 py-4 sm:flex sm:items-center sm:justify-between">
      <div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-cyan-700">{company.name}</p><h1 className="mt-1 text-xl font-semibold tracking-tight text-slate-950">Biblioteca de conhecimento</h1></div>
      {canManage && <button onClick={onConnect} className="mt-3 inline-flex items-center gap-2 rounded-xl bg-slate-950 px-3.5 py-2 text-sm font-semibold text-white hover:bg-slate-800 sm:mt-0"><Plus size={16} />Adicionar fonte</button>}
    </div>
    <div className="grid min-h-[calc(100vh-12rem)] xl:grid-cols-[250px_minmax(0,1fr)_300px]">
      <aside id="library-sources" className="border-b border-slate-200 bg-slate-50/80 xl:border-b-0 xl:border-r">
        <div className="flex items-center justify-between px-4 pb-3 pt-4"><div><p className="text-sm font-semibold text-slate-900">Fontes</p><p className="mt-0.5 text-xs text-slate-500">Dados conectados</p></div><button onClick={loadLibrary} className="rounded-lg p-2 text-slate-500 hover:bg-slate-200" aria-label="Atualizar biblioteca"><RefreshCw size={15} /></button></div>
        <nav className="flex flex-wrap items-center gap-1 px-3 pb-3 text-xs" aria-label="Caminho das fontes"><button onClick={() => openPath([])} className={`rounded-md px-2 py-1.5 ${path.length === 0 ? "bg-white font-semibold text-slate-900 shadow-sm" : "text-cyan-700 hover:bg-cyan-50"}`}>Biblioteca</button>{path.map((node, index) => <span key={node.id} className="flex items-center"><ChevronRight size={13} className="text-slate-400" /><button onClick={() => openPath(path.slice(0, index + 1))} className={`max-w-24 truncate rounded-md px-1.5 py-1.5 ${index === path.length - 1 ? "bg-white font-semibold text-slate-900 shadow-sm" : "text-cyan-700 hover:bg-cyan-50"}`}>{node.name}</button></span>)}</nav>
        <div className="max-h-72 overflow-y-auto px-2 pb-4 xl:max-h-[calc(100vh-20rem)]">{libraryLoading ? <p className="px-2 py-5 text-sm text-slate-500">Abrindo fontes…</p> : items.length === 0 ? <div className="px-2 py-5 text-sm text-slate-500"><HardDrive size={18} className="mb-2 text-cyan-700" />{current ? "Esta pasta ainda não possui itens." : "Nenhuma fonte sincronizada."}</div> : items.map((item) => <div key={item.id} className="group flex items-center rounded-xl hover:bg-white"><button onClick={() => openItem(item)} className="flex min-w-0 flex-1 items-center gap-2 px-2.5 py-2 text-left text-sm"><span className={`grid size-7 shrink-0 place-items-center rounded-lg ${item.kind === "file" ? "bg-slate-200 text-slate-600" : "bg-cyan-100 text-cyan-800"}`}>{item.kind === "file" ? <FileText size={14} /> : <FolderOpen size={14} />}</span><span className="min-w-0 flex-1 truncate font-medium text-slate-700">{item.name}</span>{item.kind !== "file" && <ChevronRight size={14} className="text-slate-400" />}</button>{canManage && item.kind === "file" && (item.workspace_documents?.length ?? 0) > 0 && <button onClick={() => manageFile(item)} className="mr-1 rounded-lg p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-800" aria-label={`Gerenciar ${item.name}`} title="Gerenciar arquivo"><Settings2 size={15} /></button>}</div>)}</div>
        {pagination && pagination.pages > 1 && <div className="flex items-center justify-between border-t border-slate-200 px-4 py-3 text-xs text-slate-500"><span>{pagination.page}/{pagination.pages}</span><div className="flex gap-1"><button disabled={pagination.page === 1} onClick={() => setPage((value) => Math.max(1, value - 1))} className="rounded px-2 py-1 hover:bg-white disabled:opacity-40">←</button><button disabled={pagination.page === pagination.pages} onClick={() => setPage((value) => Math.min(pagination.pages, value + 1))} className="rounded px-2 py-1 hover:bg-white disabled:opacity-40">→</button></div></div>}
      </aside>
      <main id="consultas" className="flex min-h-[560px] min-w-0 flex-col bg-white">
        <div className="border-b border-slate-100 px-5 py-4 sm:px-7"><p className="text-sm font-semibold text-slate-900">Conversa</p><p className="mt-1 text-sm text-slate-500">Pergunte sobre seus documentos e receba respostas com evidências.</p>{activeContext ? <span className="mt-3 inline-flex items-center gap-1.5 rounded-full bg-cyan-50 px-2.5 py-1 text-xs font-semibold text-cyan-800"><Sparkles size={13} />Usando: {activeContext.name}</span> : <span className="mt-3 inline-block rounded-full bg-amber-50 px-2.5 py-1 text-xs font-medium text-amber-800">Escolha uma fonte de contexto à direita</span>}</div>
        <div className="flex-1 overflow-y-auto px-5 py-6 sm:px-7">{messages.length > 0 ? <div className="mx-auto max-w-3xl space-y-5">{messages.map((message) => message.role === "user" ? <div key={message.id} className="ml-auto max-w-[85%]"><p className="mb-1 text-right text-xs font-medium text-slate-400">{message.contextName}</p><div className="rounded-2xl rounded-br-md bg-slate-950 px-4 py-3 text-sm leading-6 text-white">{message.content}</div></div> : <article key={message.id} className="rounded-2xl border border-slate-200 bg-slate-50/70 p-5"><div className="flex items-center gap-2"><span className="grid size-7 place-items-center rounded-lg bg-cyan-100 text-cyan-800"><Sparkles size={15} /></span><div><p className="text-sm font-semibold text-slate-900">Resposta da IA</p><p className="text-xs text-slate-500">{message.contextName}</p></div></div>{message.pending ? <p className="mt-4 text-sm text-slate-500">Consultando evidências…</p> : message.error ? <p className="mt-4 text-sm leading-6 text-rose-700">Não foi possível concluir esta pergunta: {message.error}</p> : message.answer ? <><p className="mt-4 whitespace-pre-wrap text-sm leading-7 text-slate-700">{message.answer.answer ?? retrievalMessage(message.answer.retrieval_status)}</p>{message.answer.citations.length > 0 && <div className="mt-5 border-t border-slate-200 pt-4"><p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">Fontes citadas</p><div className="space-y-2">{message.answer.citations.map((item) => <EvidenceCard key={`${message.id}-${item.document_id}-${item.page_number ?? 0}`} item={item} />)}</div></div>}</> : null}</article>)}</div> : <div className="mx-auto flex h-full max-w-md flex-col items-center justify-center py-16 text-center"><span className="grid size-12 place-items-center rounded-2xl bg-cyan-50 text-cyan-800"><Sparkles size={22} /></span><h2 className="mt-4 text-lg font-semibold text-slate-900">O que você quer descobrir?</h2><p className="mt-2 text-sm leading-6 text-slate-500">Escolha um escopo sincronizado e faça uma pergunta. A resposta indicará os documentos que a sustentam.</p></div>}</div>
        <form onSubmit={(event) => { void ask(event); }} className="border-t border-slate-200 bg-white p-4 sm:px-7 sm:py-5"><div className="rounded-2xl border border-slate-300 bg-white p-2 shadow-sm focus-within:border-cyan-500 focus-within:ring-2 focus-within:ring-cyan-100"><textarea value={question} onChange={(event) => setQuestion(event.target.value)} maxLength={1000} rows={3} placeholder={activeContext?.query_status === "ready" ? "Faça uma pergunta sobre este escopo…" : "Escolha um escopo pronto para perguntas"} className="w-full resize-none border-0 bg-transparent px-2 py-1 text-sm outline-none placeholder:text-slate-400" /><div className="flex items-center justify-between border-t border-slate-100 px-2 pt-2"><span className="text-xs text-slate-400">{question.length}/1000</span><button disabled={activeContext?.query_status !== "ready" || !question.trim() || asking} className="inline-flex items-center gap-2 rounded-xl bg-slate-950 px-3 py-2 text-sm font-semibold text-white hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-40"><Send size={15} />{asking ? "Consultando…" : "Enviar"}</button></div></div><p className="mt-2 text-xs text-slate-400">A IA usa somente o escopo selecionado e não responde sem evidência suficiente.</p></form>
      </main>
      <aside className="border-t border-slate-200 bg-slate-50/50 xl:border-l xl:border-t-0">
        <section className="border-b border-slate-200 p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-semibold text-slate-900">Contexto da conversa</p><p className="mt-1 text-xs leading-5 text-slate-500">Defina os documentos que a IA pode consultar.</p></div><Sparkles size={17} className="mt-0.5 shrink-0 text-cyan-700" /></div><select value={contextId} onChange={(event) => setContextId(event.target.value)} className="mt-3 w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-cyan-600"><option value="">Selecione um escopo sincronizado</option>{contexts.map((item) => <option key={item.id} value={item.id} disabled={item.query_status !== "ready"}>{item.name} · {contextStatusLabel(item)}</option>)}</select>{contexts.length === 0 ? <p className="mt-2 text-xs leading-5 text-amber-800">Ainda não há escopos prontos. Sincronize uma fonte para começar.</p> : !contexts.some((item) => item.query_status === "ready") && <p className="mt-2 text-xs leading-5 text-amber-800">Os escopos disponíveis ainda não possuem conteúdo pronto para IA.</p>}</section>
        <section className="border-b border-slate-200 p-4"><p className="text-sm font-semibold text-slate-900">Encontrar na biblioteca</p><form onSubmit={(event) => { void searchLibrary(event); }} className="mt-3 flex gap-2"><input value={query} onChange={(event) => setQuery(event.target.value)} maxLength={500} placeholder="Nome de arquivo ou pasta" className="min-w-0 flex-1 rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-cyan-600" /><button className="rounded-xl border border-slate-300 bg-white px-3 text-slate-600 hover:bg-slate-100" aria-label="Buscar na biblioteca"><Search size={16} /></button></form>{query && results.length === 0 && <p className="mt-3 text-xs text-slate-500">Nenhum nome encontrado.</p>}{results.length > 0 && <div className="mt-3 max-h-40 space-y-1 overflow-auto">{results.map((item) => <button key={item.id} onClick={() => openItem(item)} className="flex w-full items-center gap-2 rounded-lg px-2 py-2 text-left text-sm hover:bg-white"><span className="text-cyan-700">{item.kind === "file" ? <FileText size={14} /> : <FolderOpen size={14} />}</span><span className="min-w-0 flex-1 truncate">{item.name}</span></button>)}</div>}<p className="mt-2 text-xs leading-5 text-slate-400">Busca por nome e navegação; não lê o conteúdo dos documentos.</p></section>
        <section className="p-4"><div className="flex items-start justify-between gap-2"><div><p className="text-sm font-semibold text-slate-900">Sincronizações</p><p className="mt-1 text-xs text-slate-500">Atualiza enquanto houver atividade.</p></div><button onClick={loadOperations} className="rounded-lg p-2 text-slate-500 hover:bg-white" aria-label="Atualizar sincronizações"><RefreshCw size={15} /></button></div><div className="mt-3 space-y-2">{visibleSyncs.length === 0 ? <p className="text-sm text-slate-500">Nenhuma sincronização ainda.</p> : visibleSyncs.map((item) => <div key={item.id} className="rounded-xl border border-slate-200 bg-white p-3"><div className="flex items-start justify-between gap-2"><b className="min-w-0 truncate text-sm text-slate-800">{item.workspace_name}</b><span className={`shrink-0 rounded-full px-2 py-0.5 text-[11px] font-semibold ${item.status === "failed" ? "bg-rose-100 text-rose-700" : item.status === "partial_failure" ? "bg-amber-100 text-amber-800" : item.status === "syncing" ? "bg-cyan-100 text-cyan-800" : item.status === "queued" ? "bg-violet-100 text-violet-700" : "bg-emerald-100 text-emerald-800"}`}>{item.status === "syncing" ? "Sincronizando" : item.status === "queued" ? "Na fila" : item.status === "ready" ? "Concluída" : item.status === "partial_failure" ? "Com falhas" : "Falhou"}</span></div>{item.error_code && <p className="mt-1 text-xs text-rose-700">{item.error_code}</p>}<p className="mt-1 text-xs text-slate-400">{item.completed_at ? new Date(item.completed_at).toLocaleString("pt-BR") : item.started_at ? "Em andamento" : "Aguardando início"}</p></div>)}</div></section>
      </aside>
    </div>
  </div>{managedFile && managedDocument && <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4" role="dialog" aria-modal="true" aria-labelledby="manage-file-title"><section className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-wide text-cyan-700">Índice local</p><h2 id="manage-file-title" className="mt-1 text-xl font-semibold text-slate-950">Gerenciar arquivo</h2></div><button disabled={managingFile} onClick={() => { setManagedFile(null); setManagedDocument(null); }} className="rounded-lg p-2 text-slate-500 hover:bg-slate-100" aria-label="Fechar"><X size={18} /></button></div><div className="mt-5 rounded-xl bg-slate-50 p-4"><p className="font-medium text-slate-900">{managedFile.name}</p><p className="mt-1 text-sm leading-6 text-slate-500">As ações abaixo afetam somente a cópia indexada. O original não será apagado do Google Drive.</p></div>{managedReferences.length > 1 && <label className="mt-5 block text-sm font-medium text-slate-700">Espaço de conhecimento<select value={managedDocument.document_id} disabled={managingFile} onChange={(event) => setManagedDocument(managedReferences.find((item) => item.document_id === event.target.value) ?? null)} className="mt-2 w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="">Selecione um espaço</option>{managedReferences.map((reference) => <option key={reference.document_id} value={reference.document_id}>{contexts.find((item) => item.id === reference.workspace_folder_id)?.name ?? "Espaço sincronizado"}</option>)}</select></label>}<p className="mt-4 text-xs text-slate-500">{managedContext ? `Espaço selecionado: ${managedContext.name}` : "Espaço selecionado para esta cópia."}</p><div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button disabled={managingFile} onClick={() => { void removeManagedFile(); }} className="inline-flex items-center justify-center gap-2 rounded-xl border border-rose-200 px-4 py-2.5 text-sm font-semibold text-rose-700 hover:bg-rose-50 disabled:opacity-50"><Trash2 size={16} />Remover do índice</button><button disabled={managingFile} onClick={() => { void reprocessManagedFile(); }} className="inline-flex items-center justify-center gap-2 rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white hover:bg-slate-800 disabled:opacity-50"><RefreshCw size={16} />{managingFile ? "Aguarde…" : "Reprocessar"}</button></div></section></div>}</>;
}

function EvidenceCard({ item }: { item: Evidence }) {
  const passages = item.citation_count ?? 1;
  const body = <><FileText size={14} className="shrink-0 text-cyan-700" /><b className="min-w-0 flex-1 truncate text-sm">{item.document_name}</b>{passages > 1 && <span className="shrink-0 rounded-full bg-cyan-50 px-2 py-0.5 text-[11px] font-semibold text-cyan-800">{passages} trechos</span>}{passages === 1 && item.page_number && <span className="shrink-0 text-xs text-slate-400">p. {item.page_number}</span>}</>;
  const className = "flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-slate-700";
  return item.source_url ? <a href={item.source_url} target="_blank" rel="noreferrer" className={`${className} hover:border-cyan-300 hover:bg-cyan-50/30`} aria-label={`Abrir fonte: ${item.document_name}`}>{body}</a> : <div className={className}>{body}</div>;
}

function TeamScreen({ company, setError, setNotice }: { company: Company; setError: (value: string | null) => void; setNotice: (value: string | null) => void }) {
  const [members, setMembers] = useState<Member[]>([]); const [email, setEmail] = useState(""); const [role, setRole] = useState<"admin" | "member">("member"); const [busy, setBusy] = useState(false);
  const load = useCallback(() => { if (company.role !== "owner") return; void api<Member[]>(`/organizations/${company.id}/members`).then(setMembers).catch((caught) => setError(messageFor(caught))); }, [company.id, company.role, setError]);
  useEffect(() => { load(); }, [load]);
  if (company.role !== "owner") return <Restricted title="Apenas o Owner gerencia a equipe" description="Admins e Members podem usar pastas compartilhadas, mas não veem nem alteram membros ou convites." />;
  async function invite(event: FormEvent) { event.preventDefault(); setBusy(true); try { await api<{ status: string }>(`/organizations/${company.id}/members/invitations`, { method: "POST", body: JSON.stringify({ email, role }) }); setEmail(""); setNotice("Convite enviado."); } catch (caught) { setError(messageFor(caught)); } finally { setBusy(false); } }
  async function change(member: Member, next: "admin" | "member") { try { await api<Member>(`/organizations/${company.id}/members/${member.id}`, { method: "PATCH", body: JSON.stringify({ role: next }) }); load(); } catch (caught) { setError(messageFor(caught)); } }
  async function remove(member: Member) { if (!window.confirm(`Remover ${member.email} da Company?`)) return; try { await api<void>(`/organizations/${company.id}/members/${member.id}`, { method: "DELETE" }); setMembers((items) => items.filter((item) => item.id !== member.id)); } catch (caught) { setError(messageFor(caught)); } }
  return <div className="grid gap-5 lg:grid-cols-[1fr_330px]"><section className="rounded-2xl border bg-white p-6"><p className="text-sm font-semibold text-cyan-700">Acesso da Company</p><h1 className="mt-1 text-2xl font-semibold">Equipe</h1><div className="mt-5 space-y-3">{members.map((member) => <div key={member.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border p-4"><div><b className="text-sm">{member.email}</b><p className="mt-1 text-xs capitalize text-slate-500">{member.role}</p></div>{member.role !== "owner" && <div className="flex items-center gap-2"><select value={member.role} onChange={(event) => { void change(member, event.target.value as "admin" | "member"); }} className="rounded-lg border px-2 py-1.5 text-sm"><option value="admin">Admin</option><option value="member">Member</option></select><button onClick={() => { void remove(member); }} className="rounded-lg p-2 text-rose-600 hover:bg-rose-50" aria-label={`Remover ${member.email}`}><Trash2 size={16} /></button></div>}</div>)}</div></section><form onSubmit={invite} className="h-fit rounded-2xl border bg-white p-6"><h2 className="font-semibold">Convidar pessoa</h2><p className="mt-2 text-sm leading-6 text-slate-500">Owners controlam acesso. Admins organizam fontes; Members pesquisam e perguntam.</p><input required value={email} onChange={(event) => setEmail(event.target.value)} type="email" placeholder="pessoa@empresa.com" className="mt-5 w-full rounded-xl border px-3 py-2.5" /><select value={role} onChange={(event) => setRole(event.target.value as "admin" | "member")} className="mt-3 w-full rounded-xl border px-3 py-2.5"><option value="member">Member</option><option value="admin">Admin</option></select><button disabled={busy} className="mt-4 w-full rounded-xl bg-slate-950 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{busy ? "Enviando…" : "Enviar convite"}</button></form></div>;
}
function Restricted({ title, description }: { title: string; description: string }) { return <section className="max-w-xl rounded-2xl border bg-white p-7"><ShieldCheck className="text-slate-700" /><h1 className="mt-4 text-2xl font-semibold">{title}</h1><p className="mt-3 leading-6 text-slate-600">{description}</p></section>; }

function IntegrationScreen({ company, setError, setNotice, onOpenWorkspace }: { company: Company; setError: (value: string | null) => void; setNotice: (value: string | null) => void; onOpenWorkspace: () => void }) {
  const [sources, setSources] = useState<Source[]>([]); const [source, setSource] = useState<Source | null>(null); const [catalog, setCatalog] = useState<ScopeCatalog | null>(null); const [selectedIds, setSelectedIds] = useState<string[]>([]); const [includeRoot, setIncludeRoot] = useState(false); const [mode, setMode] = useState<"selected" | "all_accessible">("selected"); const [workspaceFolderId, setWorkspaceFolderId] = useState<string | null>(null); const [uniform, setUniform] = useState(false); const [sync, setSync] = useState<Sync | null>(null); const [failures, setFailures] = useState<FailedDocument[]>([]); const [busy, setBusy] = useState(false); const [toolModalOpen, setToolModalOpen] = useState(false); const [disconnecting, setDisconnecting] = useState(false);
  const canManage = company.role !== "member";
  const hasSelectedScope = mode === "all_accessible" || selectedIds.length > 0 || includeRoot;
  const loadSources = useCallback(() => { if (canManage) void api<Source[]>(`/data-sources?organization_id=${company.id}`).then(setSources).catch((caught) => setError(messageFor(caught))); }, [canManage, company.id, setError]);
  useEffect(() => { loadSources(); }, [loadSources]);
  useEffect(() => { if (new URLSearchParams(window.location.search).get("connected") === "google_drive") void Promise.resolve().then(() => setToolModalOpen(true)); }, []);
  if (!canManage) return <Restricted title="Apenas Owner e Admin conectam fontes" description="Members podem consultar espaços já compartilhados, mas não conectam Drive nem iniciam sincronizações." />;
  function connect(sourceId?: string) { const reauth = sourceId ? `&source_id=${encodeURIComponent(sourceId)}` : ""; window.location.assign(`${API_BASE}/data-sources/google/oauth/start?organization_id=${encodeURIComponent(company.id)}${reauth}`); }
  async function loadCatalog(selected: Source) { if (selected.status === "reauth_required") { connect(selected.id); return; } setSource(selected); setCatalog(null); setSelectedIds([]); setIncludeRoot(false); setMode("selected"); setUniform(false); try { setCatalog(await api<ScopeCatalog>(`/data-sources/${selected.id}/scope-catalog?organization_id=${company.id}`)); } catch (caught) { setError(messageFor(caught)); } }
  function toggleFolder(id: string) { setMode("selected"); setSelectedIds((ids) => ids.includes(id) ? ids.filter((item) => item !== id) : [...ids, id]); }
  async function selectAndSync() { if (!source || !uniform || !hasSelectedScope) return; setBusy(true); try { const folder = await api<{ id: string }>(`/workspace-folders/selections?organization_id=${company.id}`, { method: "POST", body: JSON.stringify({ source_id: source.id, mode, folder_ids: mode === "selected" ? selectedIds : [], include_root_files: mode === "selected" && includeRoot, uniform_access_confirmed: true }) }); setWorkspaceFolderId(folder.id); const started = await api<{ job_id: string; status: string }>(`/workspace-folders/${folder.id}/sync?organization_id=${company.id}`, { method: "POST" }); setSync({ id: started.job_id, status: started.status, error_code: null, completed_at: null }); setNotice("Sincronização iniciada. O conteúdo será indexado somente dentro deste espaço de conhecimento."); } catch (caught) { setError(messageFor(caught)); } finally { setBusy(false); } }
  async function refresh() { if (!sync || !workspaceFolderId) return; try { setSync(await api<Sync>(`/workspace-folders/${workspaceFolderId}/syncs/${sync.id}?organization_id=${company.id}`)); } catch (caught) { setError(messageFor(caught)); } }
  async function loadFailures() { if (!workspaceFolderId) return; try { setFailures(await api<FailedDocument[]>(`/workspace-folders/${workspaceFolderId}/documents/failures?organization_id=${company.id}`)); } catch (caught) { setError(messageFor(caught)); } }
  async function disconnect(selected: Source) { if (!window.confirm("Desconectar esta conta? Novas sincronizações serão bloqueadas; os dados já indexados continuarão disponíveis.")) return; setDisconnecting(true); try { await api<void>(`/data-sources/${selected.id}?organization_id=${company.id}`, { method: "DELETE" }); setSource(null); setCatalog(null); await api<Source[]>(`/data-sources?organization_id=${company.id}`).then(setSources); setToolModalOpen(false); setNotice("Google Drive desconectado. Você pode autorizar outra conta quando quiser."); } catch (caught) { setError(messageFor(caught)); } finally { setDisconnecting(false); } }
  if (!source) return <ToolsCatalog sources={sources} modalOpen={toolModalOpen} onOpen={() => setToolModalOpen(true)} onClose={() => setToolModalOpen(false)} onConnect={connect} onManage={(selected) => { setToolModalOpen(false); void loadCatalog(selected); }} onDisconnect={disconnect} disconnecting={disconnecting} />;
  return <div className="max-w-3xl"><p className="text-sm font-semibold text-cyan-700">Integração de leitura</p><h1 className="mt-1 text-3xl font-semibold">Google Drive</h1><p className="mt-2 leading-6 text-slate-600">Conecte uma fonte e defina exatamente o que será compartilhado para indexação e IA.</p><section className="mt-6 rounded-2xl border bg-white p-6"><h2 className="font-semibold">1. Fonte conectada</h2>{sources.length === 0 ? <button onClick={() => connect()} className="mt-4 rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white">Conectar Google Drive</button> : <div className="mt-4 space-y-2">{sources.map((item) => <div key={item.id} className={`flex items-center gap-3 rounded-xl border p-3 ${source?.id === item.id ? "border-cyan-400 bg-cyan-50" : ""}`}><button onClick={() => { void loadCatalog(item); }} className="min-w-0 flex-1 text-left"><span className="font-medium">{item.provider}</span><span className="ml-2 text-xs capitalize text-slate-500">{item.status}</span></button>{item.status === "reauth_required" && <button onClick={() => connect(item.id)} className="rounded-lg bg-amber-200 px-3 py-2 text-xs font-semibold text-amber-950">Reconectar</button>}</div>)}</div>}</section>{source && <section className="mt-4 rounded-2xl border bg-white p-6"><h2 className="font-semibold">2. Defina o escopo</h2><p className="mt-1 text-sm leading-6 text-slate-500">Selecione uma ou mais pastas. Cada pasta inclui subpastas; arquivos repetidos em seleções sobrepostas são processados uma única vez.</p>{catalog ? <><div className="mt-4 grid gap-2 sm:grid-cols-2">{catalog.folders.map((item) => <label key={item.id} className={`cursor-pointer rounded-xl border p-3 text-left ${mode === "selected" && selectedIds.includes(item.id) ? "border-cyan-400 bg-cyan-50" : ""}`}><input type="checkbox" checked={mode === "selected" && selectedIds.includes(item.id)} onChange={() => toggleFolder(item.id)} className="mr-2" /><FolderOpen size={16} className="mr-2 inline text-cyan-700" />{item.name}</label>)}</div><label className={`mt-4 flex cursor-pointer gap-3 rounded-xl border p-4 text-sm ${mode === "selected" && includeRoot ? "border-cyan-400 bg-cyan-50" : ""}`}><input type="checkbox" checked={mode === "selected" && includeRoot} onChange={(event) => { setMode("selected"); setIncludeRoot(event.target.checked); }} className="mt-1" /><span><b>{catalog.root_files.label}</b><span className="mt-1 block text-slate-500">Inclui somente arquivos soltos na raiz; não percorre pastas.</span></span></label><label className={`mt-3 flex cursor-pointer gap-3 rounded-xl border border-amber-200 p-4 text-sm ${mode === "all_accessible" ? "bg-amber-50" : ""}`}><input type="radio" name="drive-scope" checked={mode === "all_accessible"} onChange={() => { setMode("all_accessible"); setSelectedIds([]); setIncludeRoot(false); }} className="mt-1" /><span><b>{catalog.all_accessible.label}</b><span className="mt-1 block text-amber-900">Avançado: indexa todos os arquivos que esta conta permite ao app ler e pode aumentar custo e tempo.</span></span></label></> : <p className="mt-4 text-sm text-slate-500">Carregando as pastas disponíveis…</p>}{hasSelectedScope && <label className="mt-5 flex gap-3 rounded-xl bg-amber-50 p-4 text-sm leading-6 text-amber-950"><input type="checkbox" checked={uniform} onChange={(event) => setUniform(event.target.checked)} className="mt-1" />Confirmo que todos os membros desta Company podem acessar este conjunto de arquivos. Entendo que conteúdo elegível será enviado ao provedor de IA para indexação e respostas.</label>}<button disabled={!hasSelectedScope || !uniform || busy} onClick={() => { void selectAndSync(); }} className="mt-5 rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-40">{busy ? "Iniciando…" : "Revisar e sincronizar"}</button></section>}{sync && <section className="mt-4 rounded-2xl border bg-white p-6"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Sincronização</h2><p className="mt-1 text-sm capitalize text-slate-500">{sync.status.replaceAll("_", " ")}{sync.error_code ? ` · ${sync.error_code}` : ""}</p></div><button onClick={() => { void refresh(); }} className="rounded-lg border p-2" aria-label="Atualizar status"><RefreshCw size={17} /></button></div><div className="mt-4 flex gap-4"><button onClick={() => { void loadFailures(); }} className="text-sm font-semibold text-cyan-700">Ver falhas</button>{workspaceFolderId && <button onClick={onOpenWorkspace} className="text-sm font-semibold text-cyan-700">Abrir biblioteca</button>}</div>{failures.map((failure) => <div key={failure.id} className="mt-2 rounded-lg bg-rose-50 p-3 text-sm text-rose-800">{failure.name}: {failure.error_code ?? failure.status}</div>)}</section>}</div>;
}

function ToolsCatalog({ sources, modalOpen, onOpen, onClose, onConnect, onManage, onDisconnect, disconnecting }: { sources: Source[]; modalOpen: boolean; onOpen: () => void; onClose: () => void; onConnect: (sourceId?: string) => void; onManage: (source: Source) => void; onDisconnect: (source: Source) => void; disconnecting: boolean }) {
  const primary = sources.find((source) => source.status === "connected" || source.status === "reauth_required") ?? sources[0] ?? null;
  const connected = primary?.status === "connected";
  const statusLabel = primary?.status === "reauth_required" ? "Reconexão necessária" : primary?.status === "disconnected" ? "Desconectado" : connected ? "Conectado" : "Disponível";
  return <div className="max-w-4xl"><p className="text-sm font-semibold text-cyan-700">Integrações da Company</p><h1 className="mt-1 text-3xl font-semibold tracking-tight">Tools</h1><p className="mt-2 max-w-2xl leading-6 text-slate-600">Conecte ferramentas que alimentam a base de conhecimento da sua Company. Novas integrações aparecerão aqui.</p><section className="mt-7 max-w-xl rounded-2xl border bg-white p-5 shadow-sm"><button onClick={onOpen} className="flex w-full items-center gap-4 text-left"><span className="grid size-12 place-items-center rounded-2xl bg-cyan-50 text-cyan-700"><HardDrive size={23} /></span><span className="min-w-0 flex-1"><b className="block">Google Drive</b><span className="mt-1 block text-sm text-slate-500">Importe documentos compartilhados para pesquisa e IA, sempre em modo leitura.</span></span><ChevronRight className="text-slate-400" size={20} /></button><div className="mt-4 flex items-center gap-2 border-t pt-4 text-xs"><span className={`size-2 rounded-full ${connected ? "bg-emerald-500" : primary?.status === "reauth_required" ? "bg-amber-500" : "bg-slate-300"}`} /><span className="font-medium text-slate-600">{statusLabel}</span>{primary?.account_email && <span className="truncate text-slate-500">· {primary.account_email}</span>}</div></section>{modalOpen && <div role="dialog" aria-modal="true" aria-labelledby="google-drive-modal-title" className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4"><section className="w-full max-w-lg rounded-3xl bg-white p-6 shadow-2xl"><div className="flex items-start gap-4"><span className="grid size-11 place-items-center rounded-2xl bg-cyan-50 text-cyan-700"><HardDrive size={21} /></span><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-cyan-700">Tool</p><h2 id="google-drive-modal-title" className="mt-1 text-xl font-semibold">Google Drive</h2></div><button onClick={onClose} aria-label="Fechar" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><X size={18} /></button></div>{primary ? <div className="mt-6 rounded-2xl border bg-slate-50 p-4"><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">Conta autorizada</p><p className="mt-2 break-all font-medium text-slate-900">{primary.account_email ?? "Conta Google sem identificação disponível"}</p><p className="mt-1 text-sm text-slate-600">{statusLabel}. {primary.status === "reauth_required" ? "Autorize novamente para retomar sincronizações." : primary.status === "disconnected" ? "Autorize uma conta para retomar sincronizações." : "Esta conexão tem acesso somente leitura."}</p></div> : <div className="mt-6 rounded-2xl border bg-slate-50 p-4"><p className="font-medium">Nenhuma conta conectada</p><p className="mt-1 text-sm text-slate-600">Autorize uma conta Google para escolher pastas e sincronizar documentos.</p></div>}<div className="mt-6 flex flex-wrap justify-end gap-3">{primary?.status === "connected" && <button onClick={() => onManage(primary)} className="rounded-xl border border-slate-300 px-4 py-2.5 text-sm font-semibold text-slate-800 hover:bg-slate-50">Gerenciar escopo</button>}<button onClick={() => onConnect(primary?.id)} className="rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white hover:bg-slate-800">{primary ? "Reconectar" : "Conectar Google Drive"}</button>{primary && primary.status !== "disconnected" && <button disabled={disconnecting} onClick={() => onDisconnect(primary)} className="inline-flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold text-rose-700 hover:bg-rose-50 disabled:opacity-50"><Unplug size={16} />{disconnecting ? "Desconectando…" : "Desconectar"}</button>}</div><p className="mt-5 text-xs leading-5 text-slate-500">Desconectar remove a autorização salva neste produto e bloqueia novas sincronizações. Os dados já indexados não são apagados.</p></section></div>}</div>;
}

function StaffCenter({ user, onBack }: { user: User; onBack: () => void }) {
  const [companies, setCompanies] = useState<StaffCompany[]>([]); const [overview, setOverview] = useState<StaffOverview | null>(null); const [error, setError] = useState<string | null>(null); const [loading, setLoading] = useState(true);
  useEffect(() => { if (!user.is_platform_staff) return; void api<StaffCompany[]>("/platform/companies").then(setCompanies).catch((caught) => setError(messageFor(caught))).finally(() => setLoading(false)); }, [user.is_platform_staff]);
  async function open(company: StaffCompany) { try { setOverview(await api<StaffOverview>(`/platform/companies/${company.organization_id}/overview`)); } catch (caught) { setError(messageFor(caught)); } }
  if (!user.is_platform_staff) return <main className="grid min-h-screen place-items-center bg-slate-950 p-6 text-white"><section className="max-w-md text-center"><ShieldCheck className="mx-auto text-slate-400" /><h1 className="mt-4 text-2xl font-semibold">Área de suporte indisponível</h1><p className="mt-3 text-slate-300">Seu usuário não tem papel global de staff.</p><button onClick={onBack} className="mt-5 rounded-xl bg-white px-4 py-2 text-sm font-semibold text-slate-900">Voltar</button></section></main>;
  return <main className="min-h-screen bg-violet-50 text-slate-900"><header className="border-b border-violet-200 bg-white"><div className="mx-auto flex max-w-6xl items-center gap-3 px-5 py-4"><ShieldCheck className="text-violet-700" /><div><b>Modo suporte</b><p className="text-xs text-slate-500">Metadados somente; conteúdo de cliente permanece inacessível.</p></div><button onClick={onBack} className="ml-auto rounded-lg border px-3 py-2 text-sm">Voltar ao produto</button></div></header><div className="mx-auto grid max-w-6xl gap-5 p-5 lg:grid-cols-[330px_1fr]"><aside className="rounded-2xl border border-violet-100 bg-white p-4"><h1 className="font-semibold">Companies com grant ativo</h1>{loading && <p className="mt-4 text-sm text-slate-500">Carregando grants…</p>}{error && <p className="mt-4 text-sm text-rose-700">{error}</p>}<div className="mt-4 space-y-2">{companies.map((company) => <button key={company.grant_id} onClick={() => { void open(company); }} className="w-full rounded-xl border p-3 text-left hover:border-violet-300"><b className="text-sm">{company.name}</b><span className="mt-1 block text-xs text-slate-500">Expira {new Date(company.expires_at).toLocaleString("pt-BR")}</span></button>)}</div></aside><section>{overview ? <StaffOverviewCard overview={overview} /> : <div className="rounded-2xl border border-dashed border-violet-200 bg-white p-8 text-slate-600">Selecione uma Company com grant ativo. Esta área não oferece busca, documentos, links de fonte, perguntas, consultas salvas ou ações de Drive.</div>}</section></div></main>;
}
function StaffOverviewCard({ overview }: { overview: StaffOverview }) { return <section><div className="rounded-2xl border border-violet-300 bg-violet-100 p-5 text-violet-950"><b>Acesso temporário de suporte</b><p className="mt-1 text-sm">Motivo: {overview.reason} · expira em {new Date(overview.expires_at).toLocaleString("pt-BR")}</p></div><div className="mt-5 rounded-2xl border bg-white p-6"><h1 className="text-xl font-semibold">Visão operacional</h1><p className="mt-2 text-sm text-slate-500">Somente estado de pastas e resumo agregado de códigos seguros de falha.</p><div className="mt-5 space-y-3">{overview.folders.map((folder) => <div key={folder.id} className="rounded-xl border p-4"><b>{folder.name}</b><span className="ml-2 text-xs capitalize text-slate-500">{folder.status.replaceAll("_", " ")}</span>{folder.failure_summary.map((failure) => <p key={failure.error_code} className="mt-2 text-xs text-rose-700">{failure.count} falha(s): {failure.error_code}</p>)}</div>)}</div></div></section>; }

